224	    /**
225	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
226	     */
227	    public String getDisplayName() {
228	        return this.getLastName() + ", " + this.getFirstName();
229	    }
230	
231	    /**
232	     * The owner's initials: the upper-cased first letters of firstName and lastName,
233	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
234	     */
235	    public String getInitials() {
236	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
237	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
238	    }
239	
240	    /**
241	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
242	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
243	     */
244	    public String getMembershipNumber() {
245	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
246	    }
247	
248	    /**
249	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
250	     * contained in the owner's {@link #customerCode}.
251	     */
252	    public int getCheckDigit() {
253	        return luhnCheckDigit(this.customerCode);
254	    }
255	
256	    /**
257	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
258	     * contained in {@code value}. Reading the digits right to left, every second one is
259	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
260	     * digits are summed, and the check digit is the amount that must be added to that sum to
261	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
262	     * the digit is taken over exactly the digits the string carries.
263	     */
264	    private static int luhnCheckDigit(String value) {
265	        int sum = 0;
266	        boolean doubling = true;
267	        for (int i = value.length() - 1; i >= 0; i--) {
268	            char c = value.charAt(i);
269	            if (c < '0' || c > '9') {
270	                continue;
271	            }
272	            int digit = c - '0';
273	            if (doubling) {
274	                digit *= 2;
275	                if (digit > 9) {
276	                    digit -= 9;
277	                }
278	            }
279	            sum += digit;
280	            doubling = !doubling;
281	        }
282	        return (10 - (sum % 10)) % 10;
283	    }
284	
285	    /** Fixed city-to-region table used to derive an owner's locality. */
286	    private static final Map<String, String> CITY_REGION = Map.of(
287	        "Sydney", "NSW",
288	        "Melbourne", "VIC",
289	        "Brisbane", "QLD");
290	
291	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
292	    public static final String UNKNOWN_REGION = "UNKNOWN";
293	
294	    /**
295	     * The canonical region for a city, derived from the fixed city-to-region table
296	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
297	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
298	     * source of the city-to-region mapping, shared by every rule that is keyed by
299	     * region so the mapping is never re-derived elsewhere.
300	     */
301	    public static String regionOf(String city) {
302	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
303	    }
304	
305	    /**
306	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
307	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
308	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
309	     * known region). Locality is read from the region-and-hash identity so it never re-derives
310	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
311	     */
312	    public String getLocality() {
313	        if (this.customerCode == null) {
314	            return UNKNOWN_REGION;
315	        }
316	        int dash = this.customerCode.indexOf('-');
317	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
318	    }
319	
320	    /**
321	     * The region derived from this owner's postcode alone: the region whose fixed
322	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
323	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
324	     * component built into the owner's customer code at creation and, through it, the source of the
325	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
326	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
327	     */
328	    public String getRegion() {
329	        return regionOfPostcode(this.postcode);
330	    }
331	
332	    /**
333	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
334	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
335	     * no known range.
336	     */
337	    private static String regionOfPostcode(String postcode) {
338	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
339	            return null;
340	        }
341	        int value = Integer.parseInt(postcode);
342	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
343	            int[] range = entry.getValue();
344	            if (value >= range[0] && value <= range[1]) {
345	                return entry.getKey();
346	            }
347	        }
348	        return null;
349	    }
350	
351	    /**
352	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
353	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
354	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
355	     */
356	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
357	        "NSW", new int[] {2000, 2099},
358	        "VIC", new int[] {3000, 3099},
359	        "QLD", new int[] {4000, 4099});
360	
361	    /**
362	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
363	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
364	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
365	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
366	     * city with no known region accepts any 4-digit postcode.
367	     */
368	    public boolean isPostcodeValid() {
369	        if (this.postcode == null) {
370	            return true;
371	        }
372	        if (!this.postcode.matches("[0-9]{4}")) {
373	            return false;
374	        }
375	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
376	        if (range == null) {
377	            return true;
378	        }
379	        int value = Integer.parseInt(this.postcode);
380	        return value >= range[0] && value <= range[1];
381	    }
382	
383	    /**
384	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
385	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
386	     * Level 4 is reserved for tenure.
387	     */
388	    public Integer getMembershipLevel() {
389	        int level = 1;
390	        if (this.email != null && !this.email.isEmpty()) {
391	            level++;
392	        }
393	        if (this.namesakeCount != null && this.namesakeCount == 0) {
394	            level++;
395	        }
396	        return Math.min(level, 3);
397	    }
398	
399	    /**
400	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
401	     * otherwise {@code 'PHONE'}.
402	     */
403	    public String getContactPreference() {
404	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
405	    }
406	
407	    /**
408	     * The owner's identity key: the single derived value used for duplicate detection.
409	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
410	     * empty string when absent) and the householdId (or the empty string when the owner
411	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
412	     * Two owners are duplicates only when their whole identity keys are equal.
413	     */
414	    public String getIdentityKey() {
415	        String telephonePart = this.telephone == null ? "" : this.telephone;
416	        String emailPart = this.email == null ? "" : this.email;
417	        String householdPart = this.householdId == null ? "" : this.householdId;
418	        return telephonePart + "|" + emailPart + "|" + householdPart;
419	    }
420	
421	    protected Set<Pet> getPetsInternal() {
422	        if (this.pets == null) {
423	            this.pets = new HashSet<>();
424	        }
425	        return this.pets;
426	    }
427	
428	    protected void setPetsInternal(Set<Pet> pets) {
429	        this.pets = pets;
430	    }
431	
432	    public List<Pet> getPets() {
433	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
434	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
435	        return Collections.unmodifiableList(sortedPets);
436	    }
437	
438	    public void setPets(List<Pet> pets) {
439	        this.pets = new HashSet<>(pets);
440	    }
441	
442	    public void addPet(Pet pet) {
443	        getPetsInternal().add(pet);
444	        pet.setOwner(this);
445	    }
446	
447	    /**
448	     * Return the Pet with the given name, or null if none found for this Owner.
449	     *
450	     * @param name to test
451	     * @return true if pet name is already in use
452	     */
453	    public Pet getPet(String name) {
454	        return getPet(name, false);
455	    }
456	
457	    /**
458	     * Return the Pet with the given name, or null if none found for this Owner.
459	     *
460	     * @param name to test
461	     * @return true if pet name is already in use
462	     */
463	    public Pet getPet(String name, boolean ignoreNew) {
464	        name = name.toLowerCase();
465	        for (Pet pet : getPetsInternal()) {
466	            if (!ignoreNew || !pet.isNew()) {
467	                String compName = pet.getName();
468	                compName = compName.toLowerCase();
469	                if (compName.equals(name)) {
470	                    return pet;
471	                }
472	            }
473	        }
474	        return null;
475	    }
476	
477	    public Pet getPet(Integer petId) {
478	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
479	    }
480	
481	    @Override
482	    public String toString() {
483	        return new ToStringCreator(this)
484	
485	            .append("id", this.getId())
486	            .append("new", this.isNew())
487	            .append("lastName", this.getLastName())
488	            .append("firstName", this.getFirstName())
489	            .append("address", this.address)
490	            .append("city", this.city)
491	            .append("telephone", this.telephone)
492	            .append("email", this.email)
493	            .toString();
494	    }
495	}
