375	    /**
376	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
377	     * cannot form a valid E.164 number.
378	     *
379	     * <p>A leading '+' and country code are kept when present; otherwise country code
380	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
381	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
382	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
383	     * exactly the national-digit count that code requires (see
384	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
385	     */
386	    private String toE164(String telephone) {
387	        if (telephone == null) {
388	            return null;
389	        }
390	        boolean hasCountryCode = telephone.trim().startsWith("+");
391	        String digits = telephone.replaceAll("\\D", "");
392	        String e164;
393	        if (hasCountryCode) {
394	            e164 = digits;
395	        } else {
396	            if (digits.startsWith("0")) {
397	                digits = digits.substring(1);
398	            }
399	            e164 = "61" + digits;
400	        }
401	        if (e164.length() < 8 || e164.length() > 15) {
402	            return null;
403	        }
404	        if (!hasValidNationalLength(e164)) {
405	            return null;
406	        }
407	        return "+" + e164;
408	    }
