410	    /**
411	     * Whether the E.164 digit string (no leading '+') carries the national-number length
412	     * required by its country calling code. The longest matching known code wins; a number
413	     * whose country code is not recognised passes this check (its length is governed only by
414	     * the general 8-15 digit bound in {@link #toE164}).
415	     */
416	    private boolean hasValidNationalLength(String e164) {
417	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
418	            .filter(entry -> e164.startsWith(entry.getKey()))
419	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
420	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
421	            .orElse(true);
422	    }
