429	     * second member of an already-registered household. Two owners sharing a lastName and postcode
430	     * are therefore the same household: the second is a household duplicate.
431	     */
432	    private boolean isHouseholdDuplicate(Owner owner) {
433	        String householdId = owner.getHouseholdId();
434	        if (householdId == null) {
435	            return false;
